-- 18-source-baselines-and-standings. Reviewed uploaded workbook only; save pending edits and back up first.
-- Run ENTIRE file in DB Browser, verify counts, then Write Changes.
-- SAVEPOINT supports an existing transaction. No records are replaced.
-- 107 player + 10 team comparison baselines; official regular/postseason/combined standings kept separate from mixed worksheet totals.
PRAGMA foreign_keys=ON;
SAVEPOINT afl_remaining_18;
CREATE TEMP TABLE afl_remaining_18_0 AS SELECT id, season_id, scope, entity_type, player_id, team_id, source_kind, calculation_version, totals_json, source_import_batch_id FROM season_stat_snapshots WHERE 0;
CREATE TEMP TABLE afl_remaining_18_1 AS SELECT id, season_id, team_id, division_id, scope, source_kind, rank, wins, losses, ties, home_wins, home_losses, home_ties, away_wins, away_losses, away_ties, division_wins, division_losses, division_ties, points_for, points_against, streak, calculation_version FROM standing_snapshots WHERE 0;
CREATE TEMP TABLE afl_remaining_18_guard(ok INTEGER);
CREATE TEMP TRIGGER afl_remaining_18_check BEFORE INSERT ON afl_remaining_18_guard
BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leagues WHERE id='36c6e53f-7be2-5a94-84a8-0df871aae9fd' AND name='AFL') THEN RAISE(ROLLBACK,'Missing AFL league.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM seasons WHERE id='97808f43-a0d5-5251-bf8d-fae1643c8258' AND league_id='36c6e53f-7be2-5a94-84a8-0df871aae9fd') THEN RAISE(ROLLBACK,'Import 05 season first.') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM schema_migrations WHERE version=2) THEN RAISE(ROLLBACK,'Apply schema upgrade 10 first.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_18_0 i JOIN season_stat_snapshots t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.scope IS NOT i.scope OR t.entity_type IS NOT i.entity_type OR t.player_id IS NOT i.player_id OR t.team_id IS NOT i.team_id OR t.source_kind IS NOT i.source_kind OR t.calculation_version IS NOT i.calculation_version OR t.totals_json IS NOT i.totals_json OR t.source_import_batch_id IS NOT i.source_import_batch_id) THEN RAISE(ROLLBACK,'season_stat_snapshots: existing record differs; no overwrite.') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM afl_remaining_18_1 i JOIN standing_snapshots t ON t.id=i.id WHERE t.season_id IS NOT i.season_id OR t.team_id IS NOT i.team_id OR t.division_id IS NOT i.division_id OR t.scope IS NOT i.scope OR t.source_kind IS NOT i.source_kind OR t.rank IS NOT i.rank OR t.wins IS NOT i.wins OR t.losses IS NOT i.losses OR t.ties IS NOT i.ties OR t.home_wins IS NOT i.home_wins OR t.home_losses IS NOT i.home_losses OR t.home_ties IS NOT i.home_ties OR t.away_wins IS NOT i.away_wins OR t.away_losses IS NOT i.away_losses OR t.away_ties IS NOT i.away_ties OR t.division_wins IS NOT i.division_wins OR t.division_losses IS NOT i.division_losses OR t.division_ties IS NOT i.division_ties OR t.points_for IS NOT i.points_for OR t.points_against IS NOT i.points_against OR t.streak IS NOT i.streak OR t.calculation_version IS NOT i.calculation_version) THEN RAISE(ROLLBACK,'standing_snapshots: existing record differs; no overwrite.') END;
END;
DROP TRIGGER afl_remaining_18_check;
DROP TABLE afl_remaining_18_guard;
DROP TABLE afl_remaining_18_0;
DROP TABLE afl_remaining_18_1;
RELEASE SAVEPOINT afl_remaining_18;
PRAGMA foreign_key_check;
SELECT 'season_stat_snapshots' AS imported_table,count(*) AS reviewed_records_present FROM season_stat_snapshots t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='2abbb370-2090-5ca2-bdcb-46f16387430f' AND m.target_table='season_stat_snapshots' AND m.target_id=CAST(t.id AS TEXT))
UNION ALL
SELECT 'standing_snapshots' AS imported_table,count(*) AS reviewed_records_present FROM standing_snapshots t WHERE EXISTS(SELECT 1 FROM source_record_mappings m WHERE m.import_batch_id='2abbb370-2090-5ca2-bdcb-46f16387430f' AND m.target_table='standing_snapshots' AND m.target_id=CAST(t.id AS TEXT));
